def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))

    merged = [list(sorted_intervals[0])]

    for current in sorted_intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            last[1] = max(last[1], current[1])
        else:
            merged.append(list(current))

    return merged

import heapq


def toposort(nodes, edges):
    adj = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    seen = set()
    for src, dst in edges:
        if (src, dst) not in seen:
            seen.add((src, dst))
            adj[src].append(dst)
            in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    batches = []
    current = []
    current_sum = 0
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
        if current_sum + weight > limit:
            batches.append(current)
            current = []
            current_sum = 0
        current.append(name)
        current_sum += weight
    if current:
        batches.append(current)
    return batches

import re


def parse_env(text):
    result = {}
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        if '=' not in line:
            raise ValueError(f"Invalid line (no '='): {line!r}")

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_re.match(key):
            raise ValueError(f"Invalid key: {key!r}")

        if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
            value = value[1:-1]

        result[key] = value

    return result

def parse_sse(chunks):
    raw = b''.join(chunks)
    text = raw.decode('utf-8')
    text = text.replace('\r\n', '\n')
    lines = text.split('\n')

    results = []
    data_lines = []

    for line in lines:
        if line == '':
            if data_lines:
                data = '\n'.join(data_lines)
                data_lines = []
                if data == '[DONE]':
                    break
                results.append(data)
            else:
                data_lines = []
        elif line.startswith(':'):
            continue
        else:
            if ':' in line:
                field_name, field_value = line.split(':', 1)
                if field_value.startswith(' '):
                    field_value = field_value[1:]
            else:
                field_name = line
                field_value = ''
            if field_name == 'data':
                data_lines.append(field_value)

    return results

def fifo_admit(active, queued, budget, slots):
    for q in queued:
        if q > budget:
            raise ValueError("Queued reservation exceeds the whole budget")

    remaining_budget = budget - sum(active)
    remaining_slots = slots - len(active)

    admitted = []
    remaining = []
    blocked = False

    for q in queued:
        if blocked:
            remaining.append(q)
        elif remaining_slots > 0 and remaining_budget >= q:
            admitted.append(q)
            remaining_slots -= 1
            remaining_budget -= q
        else:
            blocked = True
            remaining.append(q)

    return (admitted, remaining)
